// Shared building blocks for the v2 (monday-style) pages. Markup and class names follow html-prototype/v2/
// (components.html is the cookbook). Styles: public/assets/v2/ (generated by scripts/build-v2-css.mjs), scoped under .v2.
import type { ReactNode } from "react";
import { mediaPath } from "../../media-path";
import { brandId } from "../../brand-icon";
import { brandTitles } from "../../brand-icons.generated";
import { V2_ICON_SPRITE, type V2IconName } from "./icon-sprite";

export type { V2IconName };

/** Bump when public/assets/v2/* changes so browsers fetch the new files. */
export const V2_VERSION = "20261064";

/** Design stylesheets: shared site.css, optional page stylesheet (public/assets/v2/pages/<page>.css) and homepage css. */
export function V2Styles({ page, home = false }: { page?: string; home?: boolean }) {
  return (
    <>
      <link rel="stylesheet" href={`/assets/v2/site.css?v=${V2_VERSION}`} />
      {home && <link rel="stylesheet" href={`/assets/v2/home.css?v=${V2_VERSION}`} />}
      {page && <link rel="stylesheet" href={`/assets/v2/pages/${page}.css?v=${V2_VERSION}`} />}
    </>
  );
}

/** Inline line-icon symbols, rendered once per page (hidden). */
export function V2IconSprite() {
  return <div hidden dangerouslySetInnerHTML={{ __html: V2_ICON_SPRITE }} />;
}

/** Line icon from the inline sprite (arrow, check, plus, chev, doc, clock, flag, key, shield, users, spark, bolt, brief...). */
export function V2Icon({ name, size, className }: { name: V2IconName; size?: number; className?: string }) {
  return (
    <svg className={className} width={size} height={size} aria-hidden="true">
      <use href={`#i-${name}`} />
    </svg>
  );
}

/** Technology and product icon from /assets/nx/icons.svg (code-brackets, react-atom, aws-cloud, docker-whale, ...). */
export function V2ProductIcon({ name, size = 26 }: { name: string; size?: number }) {
  return (
    <svg width={size} height={size} aria-hidden="true">
      <use href={`/assets/nx/icons.svg#${name}`} />
    </svg>
  );
}

/** URL of a generated v2 image (character, spot icon, scene or thumbnail) shipped in public/assets/v2/img. */
export const v2img = (name: string) => `/assets/v2/img/${name}.webp`;

/** Decorative or described v2 image. Pass alt="" when decorative. */
export function V2Img({ name, alt = "", className, width, height, priority = false }: { name: string; alt?: string; className?: string; width?: number; height?: number; priority?: boolean }) {
  return <img src={v2img(name)} alt={alt} className={className} width={width} height={height} loading={priority ? "eager" : "lazy"} decoding="async" />;
}

type Asset = { id: string; name?: string; src?: string; alt: string; width: number; height: number };

/**
 * Hero or section picture: the page's own generated image when it has one, otherwise a shipped v2 scene or
 * character image for its page family.
 */
export function V2Art({ asset, fallback, fallbackAlt = "", priority = false, className = "media" }: { asset?: Asset | null; fallback: string; fallbackAlt?: string; priority?: boolean; className?: string }) {
  if (asset) {
    return <img src={mediaPath(asset)} alt={asset.alt} width={asset.width} height={asset.height} className={className} loading={priority ? "eager" : "lazy"} decoding="async" />;
  }
  return <img src={v2img(fallback)} alt={fallbackAlt} className={className} loading={priority ? "eager" : "lazy"} decoding="async" />;
}

/** Hero breadcrumb: crumbs is the trail from site-structure breadcrumbs(). */
export function V2Crumbs({ trail }: { trail: { label: string; href?: string }[] }) {
  return (
    <ol className="crumbs">
      {trail.map((c, i) => (
        <li key={i} {...(i === trail.length - 1 ? { "aria-current": "page" as const } : {})}>
          {c.href && i < trail.length - 1 ? <a href={c.href}>{c.label}</a> : c.label}
        </li>
      ))}
    </ol>
  );
}

/** Section heading block (`.sec__head`): optional eyebrow, a big heading and a lead line. */
export function V2SectionHead({ eyebrow, title, lead, left = false, id }: { eyebrow?: ReactNode; title: ReactNode; lead?: ReactNode; left?: boolean; id?: string }) {
  return (
    <div className={`sec__head rv${left ? " sec__head--left" : ""}`}>
      {eyebrow && <p className="label">{eyebrow}</p>}
      <h2 className="big" id={id}>{title}</h2>
      {lead && <p className="lead">{lead}</p>}
    </div>
  );
}

/** Closing call-to-action band. Every v2 page ends with one just before the footer. */
export function V2CtaBand({ href = "/contact", howHref = "/how-we-work", title = "Ready to scope your project?", text = "Tell us what you need built. A short brief is enough to start the conversation." }: { href?: string; howHref?: string; title?: string; text?: string }) {
  return (
    <section className="cta-band" aria-labelledby="cta-t">
      <div className="wrap">
        <div className="cta-band__in rv">
          <div>
            <h2 id="cta-t">{title}</h2>
            <p>{text}</p>
            <span className="tiles" aria-hidden="true">
              {["fullstack", "ai", "devops", "mobile", "lead"].map((c) => (
                <img key={c} src={v2img(`char-${c}`)} alt="" loading="lazy" />
              ))}
            </span>
          </div>
          <div className="cta-band__acts">
            <a className="btn btn--white" href={href} data-track="consultation_click">
              Start a brief <V2Icon name="arrow" />
            </a>
            <a className="btn btn--ghost-w" href={howHref}>How we work</a>
          </div>
        </div>
      </div>
    </section>
  );
}

/**
 * Technology mark: the official brand logo when the tool has one (served from /brand/<id>.svg), otherwise a neat
 * monogram tile with its initials, never a mismatched line icon.
 */
export function TechMark({ name, size = 22 }: { name: string; size?: number }) {
  const id = brandId(name);
  if (id) return <img src={`/brand/${id}.svg`} alt="" title={brandTitles[id]} width={size} height={size} className="techmark" loading="lazy" decoding="async" />;
  const initials = name.replace(/\(.*\)/g, "").split(/[\s./+-]+/).filter(Boolean).slice(0, 2).map((w) => w[0]).join("").toUpperCase() || name[0]?.toUpperCase();
  return (
    <span className="techmark techmark--mono" aria-hidden="true" style={{ width: size, height: size }}>
      {initials}
    </span>
  );
}
